import java.io.*;
import java.math.*;

public class Main {
    private static final BigInteger MOD = BigInteger.valueOf(998244353);

    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);

        long nextLong() throws IOException {
            int c;
            long sign = 1;
            long x = 0;
            do {
                c = in.read();
            } while (c <= ' ' && c != -1);
            if (c == '-' || c == '+') {
                if (c == '-') {
                    sign = -1;
                }
                c = in.read();
            }
            while (c > ' ' && c != -1) {
                x = x * 10 + (c - '0');
                c = in.read();
            }
            return x * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        long n = fs.nextLong();
        long m = fs.nextLong();
        long L = fs.nextLong();
        long R = fs.nextLong();
        long k = R - L + 1;
        long product = n * m;
        BigInteger exp = BigInteger.valueOf(product);
        if (product % 2 == 1) {
            System.out.println(BigInteger.valueOf(k).modPow(exp, MOD));
        } else {
            long e = R / 2 - (L - 1) / 2;
            long o = k - e;
            BigInteger E = BigInteger.valueOf(e);
            BigInteger O = BigInteger.valueOf(o);
            BigInteger a = E.add(O).modPow(exp, MOD);
            BigInteger b = E.subtract(O).modPow(exp, MOD);
            System.out.println(a.add(b).multiply(MOD.add(BigInteger.ONE)).divide(BigInteger.valueOf(2)).mod(MOD));
        }
    }
}
